let phoneNumber='',phoneRound=1,phoneHeard=false,phonePlaying=false;
function newPhone(){let next;do{next=Array.from({length:9},()=>Math.floor(Math.random()*10)).join('')}while(next===phoneNumber);phoneNumber=next;phoneHeard=false}
function comparePhone(answer,expected){const digits=answer.replace(/[\s-]/g,'');return {digits,valid:/^\d+$/.test(digits),correct:digits===expected,positions:Array.from({length:Math.max(digits.length,expected.length)},(_,i)=>({actual:digits[i]??'—',expected:expected[i]??'—',correct:digits[i]===expected[i]}))}}
function phoneHTML(){if(!phoneNumber)newPhone();return `<div class="quiz-layout"><div class="challenge"><span>第 ${phoneRound} 题 · 电话号码</span><button class="hear-play" id="phone-play" aria-label="播放虚构电话号码">♫</button><p>¿Cuál es su número de teléfono?</p><p>听一组 9 位数字，不是真实联系电话。</p></div><form id="phone-form" class="exercise"><h3><label for="phone-answer">写下你听到的电话号码</label></h3><p>从第一位开始记录，开头的 0 也要写。可以重复听。</p><input id="phone-answer" type="text" inputmode="numeric" autocomplete="off" placeholder="输入 9 位数字" aria-describedby="phone-feedback"><button class="secondary" type="submit">检查号码</button><p id="phone-feedback" class="feedback" role="status"></p><div id="phone-comparison" class="phone-comparison" aria-live="polite"></div></form></div><div class="quiz-bottom"><button id="phone-reveal" class="secondary">查看答案</button><button id="phone-next" class="primary">下一题 →</button></div>`}
async function playPhone(){const token=generation;stopPlayback();phonePlaying=true;const button=document.getElementById('phone-play');button.disabled=true;let completed=true;try{for(const digit of phoneNumber){if(token!==generation){completed=false;break}const url=await fixedAudioUrl(Number(digit),spanish(Number(digit)));if(token!==generation){completed=false;break}if(!url)throw Error('missing audio');const audio=new Audio(url);audioPlayer=audio;await new Promise((resolve,reject)=>{audio.onended=resolve;audio.onerror=()=>reject(Error('audio failed'));audio.onpause=()=>{if(token!==generation){completed=false;resolve()}};audio.play().catch(reject)});if(token!==generation){completed=false;break}await new Promise(r=>setTimeout(r,220))}if(completed&&token===generation)phoneHeard=true}catch{if(token===generation)feedback('phone-feedback','数字音频暂时无法播放，请稍后再试。',false)}finally{if(token===generation){phonePlaying=false;audioPlayer=null;button.disabled=false}}}
function bindPhone(){if(mode!=='phone')return;phonePlaying=false;document.getElementById('phone-play').onclick=playPhone;
 document.getElementById('phone-form').onsubmit=e=>{e.preventDefault();if(phonePlaying){feedback('phone-feedback','先把号码听完吧。',null);return}if(!phoneHeard){feedback('phone-feedback','请先点击音符听完整号码。',null);return}const result=comparePhone(document.getElementById('phone-answer').value,phoneNumber);if(!result.valid){feedback('phone-feedback','请输入数字；空格和短横线可以省略。',null);return}feedback('phone-feedback',result.correct?'✓ 每一位都听对了！':'标出的位数没有匹配，看看答案，再听一遍。',result.correct);document.getElementById('phone-comparison').innerHTML=result.positions.map((p,i)=>`<span class="phone-digit ${p.correct?'good':'bad'}" aria-label="第 ${i+1} 位，填写 ${p.actual}，正确 ${p.expected}"><small>第 ${i+1} 位</small><strong>${p.actual}</strong>${p.correct?'<small>✓</small>':`<small>应为 ${p.expected}</small>`}</span>`).join('')};
 document.getElementById('phone-reveal').onclick=()=>feedback('phone-feedback','答案：'+phoneNumber.split('').join(' '),null);
 document.getElementById('phone-next').onclick=()=>{phoneRound++;newPhone();render()};
}
